object Solution {
  def isSolvable(words: Array[String], result: String): Boolean = {
    val allWords = words :+ result
    // Collect all unique characters
    val chars = allWords.flatMap(_.toCharArray).distinct
    if (chars.length > 10) return false // more than 10 unique chars, impossible

    // Map each char to an index
    val charIndex = chars.zipWithIndex.toMap

    // Leading characters cannot be zero
    val leadingChars = (words.map(_.head) :+ result.head).toSet

    // Precompute the contribution of each character in the sum
    // For each word, for each char, add 10^(pos) to that char's coefficient
    // For words on left side, add; for result on right side, subtract
    val coeffs = Array.fill(chars.length)(0)
    for (w <- words) {
      val len = w.length
      for (i <- w.indices) {
        val c = w(i)
        coeffs(charIndex(c)) += math.pow(10, len - i - 1).toInt
      }
    }
    val lenR = result.length
    for (i <- result.indices) {
      val c = result(i)
      coeffs(charIndex(c)) -= math.pow(10, lenR - i - 1).toInt
    }

    val usedDigits = Array.fill(10)(false)
    val assigned = Array.fill(chars.length)(-1)

    def backtrack(pos: Int): Boolean = {
      if (pos == chars.length) {
        // Check if sum is zero
        val sum = coeffs.zip(assigned).map { case (c, d) => c * d }.sum
        sum == 0
      } else {
        val c = chars(pos)
        val isLeading = leadingChars.contains(c)
        for (d <- 0 to 9) {
          if (!usedDigits(d) && !(d == 0 && isLeading)) {
            usedDigits(d) = true
            assigned(pos) = d
            if (backtrack(pos + 1)) return true
            usedDigits(d) = false
            assigned(pos) = -1
          }
        }
        false
      }
    }

    backtrack(0)
  }
}

